         )

mapper.select:
SELECT * FROM data_workset WHERE is_del = false
AND (work_config LIKE CONCAT('%', #{keyword}, '%') OR note LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
